<script setup lang="ts">
import { ref,watch,computed,onMounted,onUnmounted } from 'vue'
import type { Post } from '../lib/types'
import { dateLabel,secureUrl } from '../lib/format'
import { useApp } from '../stores/app'
import Icon from './Icon.vue'
import SpeechPlayer from './SpeechPlayer.vue'
import MediaGallery from './MediaGallery.vue'
const props=defineProps<{post:Post;tab?:'article'|'notes'}>(),emit=defineEmits<{close:[]}>(),app=useApp(),tab=ref(props.tab||'article'),body=ref(''),busy=ref(false),closeButton=ref<HTMLButtonElement>()
const notes=computed(()=>app.notes.filter(n=>n.post_id===props.post.id))
watch(()=>props.tab,t=>tab.value=t||'article')
async function add(){busy.value=true;try{await app.addNote(props.post.id,body.value);body.value=''}catch{}finally{busy.value=false}}
async function remove(id:string){try{await app.deleteNote(id)}catch{}}
function key(e:KeyboardEvent){if(e.key==='Escape')emit('close');if(e.key==='Tab'){const items=Array.from(document.querySelectorAll<HTMLElement>('.detail-dialog button:not([disabled]),.detail-dialog a,.detail-dialog textarea'));const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
let previous:Element|null=null
onMounted(()=>{previous=document.activeElement;closeButton.value?.focus();document.addEventListener('keydown',key);app.markRead(props.post.id)})
onUnmounted(()=>{document.removeEventListener('keydown',key);if(previous instanceof HTMLElement)previous.focus()})
</script>
<template><div class="modal-backdrop" @click.self="emit('close')" @wheel.stop @touchstart.stop @touchend.stop><section class="detail-dialog" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="detail-toolbar"><span class="eyebrow">THE FULL PICTURE</span><button ref="closeButton" class="icon-btn" aria-label="关闭详情" @click="emit('close')"><Icon name="X"/></button></header><div class="detail-scroll"><div class="article-category"><span class="category-tag">{{post.category}}</span><span>{{post.origin==='demo'?'交互演示 · 非真实新闻':post.origin==='manual'?'私人手记':post.content_kind==='project'?'平台指标观察 · 非发布公告':post.verification_status==='verified'?'来源已核验':'待核验'}}</span></div><h1 id="detail-title">{{post.title}}</h1><div class="article-byline">{{post.source_name}}<span>·</span>{{post.origin==='demo'?'演示日期':post.origin==='manual'?'手记时间':post.content_kind==='project'?'指标采集':'原文发布'}} {{dateLabel(post.source_published_at)}}</div><div class="detail-tabs"><button :class="{active:tab==='article'}" @click="tab='article'">完整解读</button><button :class="{active:tab==='notes'}" @click="tab='notes'">我的笔记 <span>{{notes.length}}</span></button></div><article v-if="tab==='article'" class="article-body"><SpeechPlayer :title="post.title" :text="post.short_summary+'。'+post.medium_summary+'。'+post.full_content"/><MediaGallery :post-id="post.id"/><div class="quick-take"><span><Icon name="Zap" :size="16"/>15 秒速读</span><p>{{post.short_summary}}</p></div><h2>一分钟，了解重点</h2><p>{{post.medium_summary}}</p><h2>值得关注的 {{post.key_points.length}} 件事</h2><ol><li v-for="point in post.key_points" :key="point">{{point}}</li></ol><h2>再往深处看</h2><div class="long-content">{{post.full_content}}</div><div class="source-block"><h3><Icon name="ShieldCheck" :size="17"/>来源与透明度</h3><dl><dt>事件时间</dt><dd>{{post.event_time?dateLabel(post.event_time):'未确定'}}</dd><dt>{{post.origin==='manual'?'手记时间':post.content_kind==='project'?'指标采集':'原文发布'}}</dt><dd>{{dateLabel(post.source_published_at)}}</dd><dt>整理时间</dt><dd>{{dateLabel(post.generated_at)}}</dd><dt>配图说明</dt><dd>{{post.image_attribution||'无配图'}}{{post.is_ai_generated_image?' · AI 生成示意图':''}}</dd><dt>内容类型</dt><dd>{{post.origin==='demo'?'虚构演示内容':post.origin==='manual'?'所有者私人手记':'AI 辅助整理 · 请以原始出处为准'}}</dd></dl><a v-if="secureUrl(post.source_url)" :href="post.source_url" target="_blank" rel="noopener noreferrer" class="source-link">{{post.origin==='demo'?'打开主题参考资料':'阅读原始出处'}}<Icon name="ArrowUpRight" :size="17"/></a><a v-for="source in post.related_sources" :key="source.url" :href="secureUrl(source.url)?source.url:undefined" target="_blank" rel="noopener noreferrer" class="source-link">{{source.name}}<Icon name="ExternalLink" :size="15"/></a></div></article><section v-else class="notes-section"><div class="notes-intro"><Icon name="LockKeyhole" :size="17"/><span>你的想法，只对你可见。{{app.demo?'演示笔记仅保存在当前浏览器。':''}}</span></div><form @submit.prevent="add"><textarea v-model="body" maxlength="5000" rows="4" placeholder="记下一个想法，或一个还没想明白的问题…" aria-label="私人笔记"></textarea><div class="note-submit"><small>{{body.length}} / 5000</small><button class="btn primary small" :disabled="busy||!body.trim()"><Icon name="Send" :size="15"/>保存笔记</button></div></form><div v-if="!notes.length" class="notes-empty"><Icon name="NotebookPen" :size="32"/><p>想法值得被留下。</p><small>写下你的第一条阅读笔记。</small></div><div v-for="note in notes" :key="note.id" class="note-card"><div><span class="tiny-orange">我的私人笔记</span><button class="icon-btn" aria-label="删除笔记" @click="remove(note.id)"><Icon name="Trash2" :size="16"/></button></div><p>{{note.body}}</p><small>{{dateLabel(note.created_at)}}</small></div></section></div></section></div></template>
